    "originalTitle": "Imperial Rescript / Oration of Emperor Augustus (27 BC–14 AD)",
    "authorOrRuler": "Augustus",
    "authorTitle": "Imperator Caesar Augustus (Roman Emperor)",
    "year": -27,
