    "fullExcerptText": "We, the Augusti, having assembled in peace, have resolved that liberty of worship shall be denied to no man whatsoever. Let each person follow the divine path that best suits their heart, so that the Supreme Divinity may look favorably upon our empire and all who dwell under our sceptre.",
